import string

def rotate_string(s):
    """Helper function to rotate the alphabet based on the rotation value."""
    alphabet = string.ascii_lowercase
    rotation = 2 * 2  # Twice twice means a shift of two places
    rotated = alphabet[rotation:] + alphabet[:rotation]
    return s.translate(str.maketrans(alphabet, rotated))

def encrypt(s):
    """Encrypt the string by rotating the alphabet twice to the right."""
    return rotate_string(rotate_string(s))
