import numpy as np

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    indices = np.searchsorted(planets, [planet1, planet2], side='left')

    if indices[0] == 0:
        return ()
    elif indices[1] == len(planets):
        return planets[indices[0] - 1:indices[0]]
    else:
        return tuple(planets[indices[0] - 1:indices[1]])

